// R31 — THE DATABASE'S SHAPE, CHECKED BY THE COMPILER (2026-10-18 — the 10/10 audit, operations F22).
//
// Read from the files, offline (the generated file itself is held to the migrations by `node scripts/db.types.mjs
// --check`, in `npm test` beside this):
//   · both clients carry the database's type — the browser's (lib/supabase) and the server's (lib/supabaseAdmin);
//   · lib/database.types says it is generated and from where, and covers the tables, views and functions the app uses;
//   · the few readers that choose a table at run time go through lib/dbTypes anyTable, by name — counted here, so a new
//     one is a decision and not a habit — and nothing else casts a client back to untyped;
//   · tsType, the generator's mapping, reads Postgres's types as supabase gen types does.
import { readFileSync, readdirSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { tsType } from "./db.types.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => readFileSync(join(ROOT, p), "utf8");
let pass = 0, fail = 0;
const ok = (n, c, got) => { if (c) pass++; else { fail++; console.log(`  ✗ ${n}` + (got !== undefined ? ` → got ${JSON.stringify(got)?.slice(0, 900)}` : "")); } };

// ── both clients typed ─────────────────────────────────────────────────────────────────────────────────────────────
const browser = read("lib/supabase.ts"), server = read("lib/supabaseAdmin.ts");
ok("lib/supabase: the browser's client is SupabaseClient<Database>, made with createClient<Database>",
  /export const supabase: SupabaseClient<Database> \| null/.test(browser) && /createClient<Database>\(/.test(browser) && /import type \{ Database \} from "\.\/database\.types"/.test(browser));
ok("lib/supabaseAdmin: the server's client is SupabaseClient<Database>, made with createClient<Database>",
  /export const supabaseAdmin: SupabaseClient<Database> \| null/.test(server) && /createClient<Database>\(/.test(server) && /import type \{ Database \} from "\.\/database\.types"/.test(server));

// ── the generated file ─────────────────────────────────────────────────────────────────────────────────────────────
const types = read("lib/database.types.ts");
ok("lib/database.types: says it is generated, by what, from what", /^\/\/ GENERATED by scripts\/db\.types\.mjs from supabase\/migrations\//.test(types));
for (const t of ["orders", "drop_orders", "delivery_orders", "shop_orders", "profiles", "push_subscriptions", "rate_limit_hits", "booking_requests"])
  ok(`lib/database.types: the table ${t} is there, with its Row, Insert, Update and Relationships`,
    new RegExp(`\\n      ${t}: \\{\\n        Row: \\{[\\s\\S]*?\\n        Insert: \\{[\\s\\S]*?\\n        Update: \\{[\\s\\S]*?\\n        Relationships: `).test(types));
for (const f of ["rate_limit_hit", "rate_limit_peek", "keep_push_device", "keep_app_push_token", "admin_set_member", "spend_credit"])
  ok(`lib/database.types: the function ${f} is there, with what it takes and returns`, new RegExp(`\\n      ${f}:\\n        \\{ Args: `).test(types));
ok("lib/database.types: no extension's functions (pg_trgm, pgcrypto live in extensions in production)", !/\n      (gin_extract_value_trgm|similarity|crypt|gen_salt):/.test(types));
ok("lib/database.types: every argument may be null (Postgres hands a function null for any of them)",
  /\n      rate_limit_hit:\n        \{ Args: \{ p_bucket: string \| null; p_window_ms: number \| null; p_max: number \| null \}; Returns: boolean \}/.test(types));
ok("lib/database.types: a nullable column reads `| null`, a NOT NULL one doesn't — and its Insert asks for it only without a default",
  /\n      orders: \{\n        Row: \{[\s\S]*?\n          total_cents: number\n/.test(types) && /\n      orders: \{[\s\S]*?Insert: \{[\s\S]*?\n          total_cents: number\n/.test(types));

// ── tsType: Postgres's types as supabase gen types reads them ────────────────────────────────────────────────────────
const E = new Set(["mood"]), R = new Map([["orders", "Tables"]]);
ok("tsType: text, uuid, timestamps and dates are strings; integers and numerics numbers; booleans booleans; json Json",
  ["text", "uuid", "timestamp with time zone", "date", "character varying(40)"].every((t) => tsType(t, E) === "string")
  && ["integer", "bigint", "numeric(10,2)", "smallint", "double precision"].every((t) => tsType(t, E) === "number")
  && tsType("boolean", E) === "boolean" && tsType("jsonb", E) === "Json" && tsType("json", E) === "Json");
ok("tsType: arrays, enums and a table's row type", tsType("text[]", E) === "string[]" && tsType("mood", E) === 'Database["public"]["Enums"]["mood"]'
  && tsType("orders", E, R) === 'Database["public"]["Tables"]["orders"]["Row"]' && tsType("void", E) === "undefined" && tsType("point", E) === "unknown");

// ── the run-time names, counted ─────────────────────────────────────────────────────────────────────────────────────
const walk = (d) => readdirSync(join(ROOT, d)).flatMap((n) => { const p = join(d, n); return statSync(join(ROOT, p)).isDirectory() ? (n === "node_modules" ? [] : walk(p)) : [p]; });
const src = ["app", "components", "lib"].flatMap(walk).filter((f) => /\.(ts|tsx)$/.test(f) && f !== "lib/database.types.ts");
const uses = {};
for (const f of src) { const n = (read(f).match(/\banyTable\(/g) || []).length; if (n && f !== "lib/dbTypes.ts") uses[f] = n; }
const EXPECTED = {
  "components/CompanyCalendar.tsx": 4,     // the calendar's nine kinds of item, each its own table (SRC)
  "components/FieldOpSheet.tsx": 2,        // an event's or a stop's sheet
  "components/crew/LocationEditor.tsx": 1, // a stop's or a venue's place
  "components/crew/OwnerDetails.tsx": 2,   // an event's or a stop's details, and its ops sibling
  "lib/tasks.ts": 1,                       // a pick-list task or a to-do
};
ok("anyTable: only where a table is chosen at run time — these files, this many times each (a new one is a decision)",
  JSON.stringify(Object.entries(uses).sort()) === JSON.stringify(Object.entries(EXPECTED).sort()), uses);
const recast = src.filter((f) => f !== "lib/dbTypes.ts" && /as unknown as SupabaseClient\b|as SupabaseClient\b(?!<)/.test(read(f)));
ok("no file casts a typed client back to an untyped one (lib/dbTypes is the one door)", recast.length === 0, recast);

// ── the pages talk to the app's own database, and to no other (security F4) ───────────────────────────────────────
const cfg = read("next.config.ts");
const connect = (cfg.match(/`connect-src [^`]*`/) || [""])[0];
ok("CSP: connect-src names the build's own Supabase project (https and wss), not every *.supabase.co",
  /\$\{DB\}/.test(connect) && !/\*\.supabase\.co/.test(connect)
  && /const DB_HOST = \(\(\) => \{ try \{ return new URL\(process\.env\.NEXT_PUBLIC_SUPABASE_URL \?\? ""\)\.host; \} catch \{ return ""; \} \}\)\(\);/.test(cfg)
  && /const DB = DB_HOST \? `https:\/\/\$\{DB_HOST\} wss:\/\/\$\{DB_HOST\}` : "https:\/\/\*\.supabase\.co wss:\/\/\*\.supabase\.co";/.test(cfg), connect);
const DBof = (url) => { let h = ""; try { h = new URL(url ?? "").host; } catch { /* none */ } return h ? `https://${h} wss://${h}` : "https://*.supabase.co wss://*.supabase.co"; };
ok("CSP: the project's address read from the URL — its host alone; none, or not a URL: the wildcard, as before",
  DBof("https://hmpxgomiiyjjxxxyzzbg.supabase.co") === "https://hmpxgomiiyjjxxxyzzbg.supabase.co wss://hmpxgomiiyjjxxxyzzbg.supabase.co"
  && DBof("https://hmpxgomiiyjjxxxyzzbg.supabase.co/") === "https://hmpxgomiiyjjxxxyzzbg.supabase.co wss://hmpxgomiiyjjxxxyzzbg.supabase.co"
  && DBof(undefined) === "https://*.supabase.co wss://*.supabase.co" && DBof("not a url") === "https://*.supabase.co wss://*.supabase.co");
ok("CSP: no plugins — object-src 'none'", /"object-src 'none'"/.test(cfg));
ok("CSP: the iPhone app's copy is the same policy (connect-src gains only the web's address)", /const appCsp = csp\n  \.replace\("connect-src 'self'", "connect-src 'self' https:\/\/app\.gt3pb\.com"\)/.test(cfg));

// ── what R30's upgrade broke: Try again on the crash screens (the 10/10 audit, front end FE11-03) ──────────────────
// Next 16.3 made 16.2's `unstable_retry` stable as `retry`; 16.4 hands an error screen only `reset` and `retry`. Read from
// the Next this lockfile installs, so the next upgrade that renames them fails here and not on a customer's crash.
const noComments = (t) => t.replace(/\/\*[\s\S]*?\*\//g, " ").split("\n").map((l) => l.replace(/(^|[^:])\/\/.*$/, "$1")).join("\n");
const boundary = readFileSync(join(ROOT, "node_modules/next/dist/client/components/error-boundary.js"), "utf8");
ok("crash screens: the installed Next hands an error screen `reset` and `retry` — the two props both screens read",
  /reset: this\.reset,\s*retry: this\.retry\b/.test(boundary) && !/unstable_retry/.test(boundary));
const ge = noComments(read("app/global-error.tsx")), er = noComments(read("app/error.tsx"));
ok("crash screens: the last one's Try again asks retry, then reset, then a fresh load — never unstable_retry",
  /export default function GlobalError\(\{ error, retry, reset \}/.test(ge) && /const again = \(\) => \(retry \?\? reset \?\? reload\)\(\);/.test(ge)
  && /onClick=\{again\}>Try again</.test(ge) && !/unstable_retry/.test(ge));
ok("crash screens: a page's Try again asks retry, then reset — never unstable_retry",
  /export default function Error\(\{ error, reset, retry \}/.test(er) && /const again = \(\) => \(retry \?\? reset\)\(\);/.test(er)
  && /onClick=\{again\}>Try again</.test(er) && !/unstable_retry/.test(er));
ok("crash screens: no file in the app reads an unstable_ prop or API of Next's",
  src.filter((f) => /\bunstable_[a-z]/i.test(noComments(read(f)))).length === 0, src.filter((f) => /\bunstable_[a-z]/i.test(noComments(read(f)))));

console.log(`\nR31 — THE DATABASE'S SHAPE, CHECKED BY THE COMPILER: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
